import java.util.Scanner;
public class ReverseArray { public static void main(String[] args){Scanner s=new Scanner(System.in);System.out.print("Enter array size (1-100): ");if(!s.hasNextInt()){System.out.println("Enter a size from 1 to 100.");return;}int n=s.nextInt();if(n<1||n>100){System.out.println("Array size must be from 1 to 100.");return;}int[] a=new int[n];for(int i=0;i<n;i++){if(!s.hasNextInt()){System.out.println("Enter exactly "+n+" whole numbers.");return;}a[i]=s.nextInt();}if(s.hasNext()){System.out.println("Enter only the array values.");return;}System.out.print("Reversed array: ");for(int i=n-1;i>=0;i--)System.out.print(a[i]+(i==0?"\n":" "));}}
